  str_homeland_secret_msg_10248 = "Tessa is great at boxing. She was the all-year-round champion in Umbraton!",
  str_homeland_secret_msg_10249 = "All of Tessa's teeth are fake. That's why she doesn't need to shy away from sweets!",
  str_homeland_secret_msg_10250 = "I saw Tessa and Smokey shopping on the street of Umbraton. They even had a drink... Hmmm...",
  str_homeland_secret_msg_10251 = "I heard that as long as Leah is around, there would be no shortage of fresh water in the dormitory.",
  str_homeland_secret_msg_10252 = "A few days ago, I saw the Navigator float to a hilltop nearby in Leah's bubble!",
  str_homeland_secret_msg_10253 = "Any flower Leah touches would bloom instantly!",
  str_homeland_secret_msg_10254 = "Last time, Novio thought Alice was a bunny and took her to the Winter Palace.",
  str_homeland_secret_msg_10255 = "Alice's two dolls were said to be picked up in the wild when she was sleepwalking one time.",
  str_homeland_secret_msg_10256 = "Alice loves spicy food. She can even breathe fire afterward!",
  str_homeland_secret_msg_10257 = "The water bottle on Sinsa's belt holds both cold and hot water for Eve.",
  str_homeland_secret_msg_10258 = "Sinsa makes a killer shish kabob. Last time he even said he'd rather be a shish kabob seller than a leader.",
  str_homeland_secret_msg_10259 = "I saw Sinsa pinning the Navigator down the last time, murmuring something about \"You can't do this.\"",
  str_homeland_secret_msg_10260 = "I heard Eve once wore something special just for the Navigator!",
  str_homeland_secret_msg_10261 = "Eve pays visits to Seleucid often lately, almost treating him like a big cat.",
  str_homeland_secret_msg_10262 = "Eve seems to be able to lift the Soroz just with one hand.",
  str_homeland_secret_msg_10263 = "Last time, I saw Eve, Sinsa, and the Navigator having a picnic together. Eve even said that they are a \"family\" or something like that...",
  str_homeland_secret_msg_10264 = "I saw Dawn giving Eve flowers the other day. They must be...",
  str_homeland_secret_msg_10265 = "The Red-Eye Gorge belongs to Dawn, but it was given to the Navigator, I heard.",
  str_homeland_secret_msg_10266 = "Dawn used to raise Eclipsites!",
  str_homeland_secret_msg_10267 = "All Taki could take is a glass of wine.",
  str_homeland_secret_msg_10268 = "Taki only came to Umbraton because he lost everything he owned gambling in the Far East.",
  str_homeland_secret_msg_10269 = "Taki's Odd Jobs hasn't had any jobs lately. It'll be going out of business soon!",
  str_homeland_secret_msg_10270 = "There are a lot more red crystals lately in the dormitory. Did someone win the lottery and start leaving gemstones around?",
  str_homeland_secret_msg_10271 = "Beryl went to see Faust a few days ago. Strange noises were heard coming from Faust's room...",
  str_homeland_secret_msg_10272 = "Rumor has it that Beryl used to be a noble of Lumopolis. She fled when her family got into some kind of trouble.",
  str_homeland_secret_msg_10273 = "Beryl's tears turn into rubies!",
  str_homeland_secret_msg_10274 = "Smokey seems to have defeated a manticore in the past! That was a legendary creature!",
  str_homeland_secret_msg_10275 = "Smokey doesn't seem to feel pain at all.",
  str_homeland_secret_msg_10276 = "When Smokey first arrived in Umbraton, she burned down a whole street...",
  str_homeland_secret_msg_10277 = "Smokey owns hundreds of pairs of sunglasses, and she wears a different pair every day.",
  str_homeland_secret_msg_10278 = "You know about that Giant Lizard in Rediesel Wrench? Fleur created it!",
  str_homeland_secret_msg_10279 = "Fleur seems to have been kidnapped by a woman with a Revolver and handed over to Rediesel Wrench.",
  str_homeland_secret_msg_10280 = "I heard that Fleur only ran away because he was harassed by his superior in Illumina.",
  str_homeland_secret_msg_10281 = "The word is, that Bonacie's home was destroyed by herself.",
  str_homeland_secret_msg_10282 = "The last time Bonacie performed in the concert, even the Soroz danced to her music.",
  str_homeland_secret_msg_10283 = "Despite how much Bonacie loves music, she can't compose at all. She just acts like she knows how to conduct.",
  str_homeland_secret_msg_10284 = "Genevieve and Smokey must be a pair, seeing how they are always together.",
  str_homeland_secret_msg_10285 = "The last time when Genevieve got drunk, I heard that she \"did something\" to the Navigator right there in the dorm...",
  str_homeland_secret_msg_10286 = "I heard that Genevieve turned her maid into a horse. That's why the horse is called \"Anna\"...",
  str_homeland_secret_msg_10287 = "Pasolo has beautiful handwriting. She practices writing every day in the dorm. That's why she always has so many pieces of paper on her.",
  str_homeland_secret_msg_10288 = "A few days ago, when the Navigator tried to tell Pasolo a story, she got upset and cried...",
  str_homeland_secret_msg_10289 = "Ever since Pasolo came to the dormitory, the floor never stayed clean. There are always pieces of paper on the ground here or there!",
  str_homeland_secret_msg_10290 = "Gram can even get drunk from drinking soda.",
  str_homeland_secret_msg_10291 = "Gram seems to be the one who cooked all the meals served in the dorm.",
  str_homeland_secret_msg_10292 = "I heard the sound of a car engine rumbling last night. Gram must've taken his car out for a spin!",
  str_homeland_secret_msg_10293 = "Revy can't have any spicy food at all. She cried for an entire day after having a Spicy Cake previously.",
  str_homeland_secret_msg_10294 = "Revy called the Navigator a \"good person\" the last time. Does that mean...",
  str_homeland_secret_msg_10295 = "Revy's sword must be made of wood. How else could she lift it?",
  str_homeland_secret_msg_10296 = "I heard the Navigator and Allura opened an antique shop together in Umbraton, selling Caelestite things for cheap!",
  str_homeland_secret_msg_10297 = "Allura seems to have invested in the Courier Union!",
  str_homeland_secret_msg_10298 = "I heard Allura only moved into the Dormitory to see if she should buy it.",
  str_homeland_secret_msg_10299 = "Paloma used to work at Lumopolis Temple. She was kicked out because she broke a statue or something.",
  str_homeland_secret_msg_10300 = "Pact and Paloma are long lost sisters!",
  str_homeland_secret_msg_10301 = "Paloma and Pittman are classmates. They actually know each other!",
  str_homeland_secret_msg_10302 = "Just the other day, I saw the Navigator riding around on Naroxel's stag. It made her furious...",
  str_homeland_secret_msg_10303 = "Naroxel seems to be able to communicate with trees. They are her eyes and ears.",
  str_homeland_secret_msg_10304 = "Naroxel is extremely afraid of cold, so she'll never go near the Northland.",
  str_homeland_secret_msg_10305 = "Tweety is an expert at snowball fights! No one in the dorm can beat her!",
  str_homeland_secret_msg_10306 = "Tweety owns a whole inn in the Far East. She's rich, as it turns out!",
  str_homeland_secret_msg_10307 = "I heard that Tweety once wanted to build a dormitory out of snow for everyone... Good thing it didn't happen.",
  str_homeland_secret_msg_10308 = "Bethel's pet seems to have eaten all the food in the dorm.",
  str_homeland_secret_msg_10309 = "Bethel is actually a famed writer in Umbraton!",
  str_homeland_secret_msg_10310 = "I heard that Bethel is the daughter of Istvan!",
  str_homeland_secret_msg_10311 = "I saw Luke sketching the Navigator the other day. It had his full attention.",
  str_homeland_secret_msg_10312 = "As soon as Luke puts on that jacket of his, he can turn into a butterfly and fly away.",
  str_homeland_secret_msg_10313 = "Never try to catch a butterfly. Luke will send in the mercs to take care of you.",
  str_homeland_secret_msg_10314 = "Pittman used to fight in the Underground Arena with Tessa in Umbraton. He was even once a champion.",
  str_homeland_secret_msg_10315 = "Pittman lost his arm to the Eclipsites in Umbraton.",
  str_homeland_secret_msg_10316 = "Pittman is a speed reader. He finishes a lot of files every day.",
  str_homeland_secret_msg_10317 = "I heard that in Lumopolis, every meal costs Hedy millions of Nightium!",
  str_homeland_secret_msg_10318 = "Just the other day, the Navigator took up Hedy's hand by mistake... and was severely punished by Pompey for it.",
  str_homeland_secret_msg_10319 = "Hedy doesn't seem happy with the dormitory. She wanted to build a new one.",
  str_homeland_secret_msg_10320 = "I saw Cordy crying to the Navigator a few days ago, and she kept on apologizing...",
  str_homeland_secret_msg_10321 = "Despite Cordy's young age, she's a senior sheriff in Illumina!",
  str_homeland_secret_msg_10322 = "Someone saw Cordy having three late meals a few days ago.",
  str_homeland_secret_msg_10323 = "I heard that Hachi and Gin plan to buy the Soroz. That's why they're here!",
  str_homeland_secret_msg_10324 = "Don't ever touch Hachi's chin. He'll panic.",
  str_homeland_secret_msg_10325 = "Gin doesn't seem to have a tail...",
  str_homeland_secret_msg_10326 = "Novio's home is a savage tribe deep in the mountains of Northland.",
  str_homeland_secret_msg_10327 = "Novio's staff seems to be able to talk!",
  str_homeland_secret_msg_10328 = "Queen Bethlehem's Winter Palace seems to be built by Novio.",
  str_homeland_secret_msg_10329 = "Lola is actually an Northland bunny-turned Aurorian!",
  str_homeland_secret_msg_10330 = "Don't touch the mark on Lola's neck, or she'll hunt you down!",
  str_homeland_secret_msg_10331 = "I passed by the kitchen just the other night and saw Lola eating in her sleep...",
  str_homeland_secret_msg_10332 = "Ever since Siobhan moved into the dorm, odd nets can be found on the roof...",
  str_homeland_secret_msg_10333 = "Siobhan is actually an ancient herself. That's why she's so interested in ancient ruins.",
  str_homeland_secret_msg_10334 = "Don't let Siobhan be together with Gronru. They won't be able to do anything if that happens.",
  str_homeland_secret_msg_10335 = "Erica doesn't seem to be from this land at all. Why else would she speak in such a weird way?",
  str_homeland_secret_msg_10336 = "Erica is actually a prophet. She foretold a lot of things that have since come true!",
  str_homeland_secret_msg_10337 = "Erica did divination for the Navigator a few days ago, saying the Navigator and Vice will...",
  str_homeland_secret_msg_10338 = "The odd cloth Florine wears seems to be bought in Illumina.",
  str_homeland_secret_msg_10339 = "Florine's sword is actually a healing staff!",
  str_homeland_secret_msg_10340 = "Florine lost her snake in the dorm...",
  str_homeland_secret_msg_10341 = "Ruby punched a hole through the wall in the dormitory while playing baseball... She almost tore the dorm down!",
  str_homeland_secret_msg_10342 = "Ruby may be an eager explorer, but she has no sense of direction.",
  str_homeland_secret_msg_10343 = "Ruby said her hamster will one day save the world...",
  str_homeland_secret_msg_10344 = "I heard that Ruby's hamster is actually her emergency ration in times of need.",
  str_homeland_secret_msg_10345 = "Rouge is actually a vegan. She just likes the smell of meat.",
  str_homeland_secret_msg_10346 = "Rouge is not really scared of ghosts. She just pretends to be afraid for Ruby's sake.",
  str_homeland_secret_msg_10347 = "Rouge only needs an hour of sleep a day, so she is just pretending to be sleeping most of the time.",
  str_homeland_secret_msg_10348 = "There are ghosts in the dorm! Rinne found it to be true as soon as she got here!",
  str_homeland_secret_msg_10349 = "Rinne seems to be able to do divination on romantic relationships. Last time, she said Yao and Amemori will...",
  str_homeland_secret_msg_10350 = "If Rinne's Kagura Bell sounds by itself, something bad is gonna happen.",
  str_homeland_secret_msg_10351 = "Rinne seems to have been a practitioner at someplace far, far away.",
  str_homeland_secret_msg_10352 = "I heard that Kayano has moved into the dorm. Has anyone ever seen her?",
  str_homeland_secret_msg_10353 = "Kayano isn't an Aurorian, is she? Why else would she be so afraid of other people?",
  str_homeland_secret_msg_10354 = "Kayano doesn't walk. She floats around.",
  str_homeland_secret_msg_10355 = "Amemori needs to sleep more than 16 hours a day, but she's just as vigilant even when she's sleeping.",
  str_homeland_secret_msg_10356 = "Amemori hates garlic!",
  str_homeland_secret_msg_10357 = "Amemori can go invisible. Everyone, be careful in the dorm!",
  str_homeland_secret_msg_10358 = "A few days ago, Yao almost ate her pillow while she slept. Really, I saw it!",
  str_homeland_secret_msg_10359 = "Yao can't swim, but she can float on the water very well.",
  str_homeland_secret_msg_10360 = "Even when Yao was just a kid, she defeated thousands of pirates!",
  str_homeland_secret_msg_10361 = "I saw Yao share with Vice a dish of \"un-spicy tofu,\" and then...",
  str_homeland_secret_msg_10362 = "Momo would secretly increase the total of the goods bought!",
  str_homeland_secret_msg_10363 = "Anzu always uses her finger to try the soup she's cooking!",
  str_homeland_secret_msg_10364 = "Momo and Anzu's ramen shop is opening a branch here!",
  str_homeland_secret_msg_10365 = "Tourdog's game made a lot of money!",
  str_homeland_secret_msg_10366 = "When in work mode, Tourdog can work for 25 hours a day!",
  str_homeland_secret_msg_10367 = "Some noble in Lumopolis seems to have invested in Tourdog...",
  str_homeland_secret_msg_10368 = "I heard that Azure would freeze the people she likes!",
  str_homeland_secret_msg_10369 = "The drunker Azure gets, the better she drives!",
  str_homeland_secret_msg_10370 = "Azure always takes the Navigator out for racing. Perhaps she would like to take him as an apprentice.",
  str_homeland_secret_msg_10371 = "Azure seems to have given her car a new nickname: Caelestite Cutie.",
  str_homeland_secret_msg_10372 = "Roy calls his robot bees not only \"Sweetie\" but also \"Caelee\" and \"Azurie\"...",
  str_homeland_secret_msg_10373 = "The last time when a Firefly's system crashed, Roy just kicked it...",
  str_homeland_secret_msg_10374 = "I once saw Roy teaching the Navigator to sew clothes. I never expected him to have the know-how...",
  str_homeland_secret_msg_10375 = "May's kitty backpack had two eyes originally. It somehow grew another pair...",
  str_homeland_secret_msg_10376 = "Whoever May's white cat talks to will receive good fortune!",
  str_homeland_secret_msg_10377 = "Last time, May gave the Navigator two ponytails. It was adorable!",
  str_homeland_secret_msg_10378 = "Lenore won't be able to move at all if she doesn't touch her ears. She said they are her \"tension springs.\"",
  str_homeland_secret_msg_10379 = "Just the other day, I saw Lenore smiling at the Navigator and inviting the Navigator to her room!",
  str_homeland_secret_msg_10380 = "If you look closely, Lenore doesn't seem to have an iris.",
  str_homeland_secret_msg_10381 = "The horns on Giles' head grow. They can grow as high as two stories!",
  str_homeland_secret_msg_10382 = "I saw Giles raising crows in the dorm the other day!",
  str_homeland_secret_msg_10383 = "As soon as Giles moved in, you can hear an eerie voice reading nursery rhymes at night in the dorm...",
  str_homeland_secret_msg_10384 = "A few days ago, Reinhardt couldn't even open a bottle and had to get the Navigator to help her.",
  str_homeland_secret_msg_10385 = "I saw Reinhardt reading a romance novel in secret!",
  str_homeland_secret_msg_10386 = "Did anyone see that old picture of Reinhardt with short hair? She was so cute!",
  str_homeland_secret_msg_10387 = "Rumor has it that Reinhardt is actually a guy!",
  str_homeland_secret_msg_10388 = "Death rays come out of Vice's eyes!",
  str_homeland_secret_msg_10389 = "I heard that Vice actually has a twin that looks exactly like her!",
  str_homeland_secret_msg_10390 = "Now that Vice got promoted, she even changed her wardrobe!",
  str_homeland_secret_msg_10391 = "I heard that {1} got sick lately, even the arm got weird...",
  str_homeland_secret_msg_10392 = "{1} was laughing like crazy in the dorm the other day, saying the day to become the \"true General of Illumina\" is close at hand... So who's the General of Illumina right now?",
  str_homeland_secret_msg_10393 = "I saw {1} using the double-tipped sword to catch fish, and he even roasted the fish with it!",
  str_homeland_secret_msg_10394 = "It's said that Vice once thought that she lost a hairpin only to find that she wore it at the back of her head.",
  str_homeland_secret_msg_10395 = "It's said that Ms. Blanc travels with a full tea set!",
  str_homeland_secret_msg_10396 = "It's said that Dove has a whole warehouse full of parcels awaiting delivery!",
  str_homeland_secret_msg_10397 = "It's said that Raphael's weapon is as heavy as a house!",
  str_homeland_secret_msg_10398 = "Nikinis would adjust the flower on her head in front of the mirror when no one is watching.",
  str_homeland_secret_msg_10399 = "It's said that Nina is an arms dealer!",
  str_homeland_secret_msg_10400 = "Ever since Nina moved in, all the curtains have become black!",
  str_homeland_secret_msg_10401 = "It's said that Nina is not afraid of ghosts at all. She actually enjoys chatting with them!",
  str_homeland_secret_msg_10402 = "Nina always has her parasol open even when she's sleeping!",
  str_homeland_secret_msg_10403 = "Sanae is a traveler from a faraway land.",
  str_homeland_secret_msg_10404 = "Sanae always talks to herself... Would she talk in her dream?",
  str_homeland_secret_msg_10405 = "The room feels so crowded with Sanae and her sister moving in...",
  str_homeland_secret_msg_10406 = "They say that Carleen is about to become the City Lady of Lumopolis!",
  str_homeland_secret_msg_10407 = "Just a few nights ago, Carleen's eyes were glowing!",
  str_homeland_secret_msg_10408 = "You know Carleen's weapon? It's formed out of Lumina and isn't actually a concrete object.",
  str_homeland_secret_msg_10409 = "Apparently Carleen has gained a new ability. They say she can control Lumopolis and make it fly around everywhere.",
  str_homeland_secret_msg_10410 = "A few days ago, Ciel was building a mecha in her sleep.",
  str_homeland_secret_msg_10411 = "Ciel's leg armor seems to be a part of her body. Nobody has seen her take it off.",
  str_homeland_secret_msg_10412 = "Ciel seems to be really good at art!",
  str_homeland_secret_msg_10413 = "Fia can communicate with animals!",
  str_homeland_secret_msg_10414 = "That Kyllo creature is supposedly Fia's family!",
  str_homeland_secret_msg_10415 = "Fia can seemingly communicate with all kinds of things, even this house!",
  str_homeland_secret_msg_10416 = "Ever since Fia moved in, a lot of shiny things have turned up. Could she be a gem dealer?",
  str_homeland_secret_msg_10417 = "Jeno's divination gets it right every time. Try it if you don't believe my words!",
  str_homeland_secret_msg_10418 = "Jeno's hands are hollow and he can hide things inside them!",
  str_homeland_secret_msg_10419 = "They say that Jeno owns lots of cards with different patterns, and each card is a prophecy of an event yet to come!",
  str_homeland_secret_msg_10420 = "Jeno actually knows nothing about magic tricks. Everything he does is real.",
  str_homeland_secret_msg_10421 = "Rainbow told me that ships have souls!",
  str_homeland_secret_msg_10422 = "I heard people say Rainbow is a descendant of an Illumina Navy deserter!",
  str_homeland_secret_msg_10423 = "Rainbow has tons of friends! But their names are very strange: Fishing Rod, Wooden Board, etc...",
  str_homeland_secret_msg_10424 = "Pollux is an angel! Someone once saw a halo above her head.",
  str_homeland_secret_msg_10425 = "Apparently... Pollux's tears can turn into gems!",
  str_homeland_secret_msg_10426 = "Pollux seems to have monopolized a lot of underground businesses in Umbraton and doesn't even take the Shadowlord seriously.",
  str_homeland_secret_msg_10427 = "Pollux is quite good with children.",
  str_homeland_secret_msg_10428 = "I heard that Casta sleeps with her rifle at night.",
  str_homeland_secret_msg_10429 = "Sometimes Casta even sleeps under her bed.",
  str_homeland_secret_msg_10430 = "Casta seems to have gotten very lucky recently. She's been winning finger-guessing games almost every time.",
  str_homeland_secret_msg_10431 = "Judge Jr. is actually a commoner. That's why he hasn't been promoted in so many years.",
  str_homeland_secret_msg_10432 = "Judge Jr. is a person played by several people who take turns putting on a mask pretending to be him.",
  str_homeland_secret_msg_10433 = "Judge Jr. doesn't actually know how to try cases. He just messes around.",
  str_homeland_secret_msg_10434 = "They say Lilica is famous in Umbraton! She came here to get away from her adoring fans!",
  str_homeland_secret_msg_10435 = "Lilica seems to have bought this dormitory. Don't forget to pay her rent!",
  str_homeland_secret_msg_10436 = "Lilica came here intending to shoot a documentary about the love and hatred that brews in this place...",
  str_homeland_secret_msg_10437 = "Lilica actually hates acting; she only does it out of consideration for her fans.",
  str_homeland_secret_msg_10438 = "They say Minos was in a gang during his days in Umbraton. Better stay on his good side...",
  str_homeland_secret_msg_10439 = "Minos is secretly raising a cow somewhere in the dormitory. That would explain the occasional moos in the night...",
  str_homeland_secret_msg_10440 = "Minos seems to be really fond of ghost stories.",
  str_homeland_secret_msg_10441 = "Even though Minos is really strong, he's actually terrified of bugs! That must be why he cleans everything so meticulously.",
  str_homeland_secret_msg_10442 = "Sadie may be small, but she's actually insanely powerful! She can pick up the whole house!",
  str_homeland_secret_msg_10443 = "Sadie says she dreams of becoming a star baseball player and that she came to Cloud Gardens to look for a place to build a baseball field!",
  str_homeland_secret_msg_10444 = "Sadie has a crazy appetite! She can eat a hundred pieces of steak without breaking a sweat, no veggies necessary!",
  str_homeland_secret_msg_10445 = "Actually, Axelia can't talk. These are all prerecorded messages.",
  str_homeland_secret_msg_10446 = "Axelia looks young, but she's a high-ranking official in the Illumina Federation.",
  str_homeland_secret_msg_10447 = "Actually, Axelia is afraid of bugs.",
  str_homeland_secret_msg_10448 = "I noticed that Axelia's bed collapsed under her a few days ago. Could she be really heavy?",
  str_homeland_secret_msg_10449 = "I heard that Beretta is quite wild in battle!",
  str_homeland_secret_msg_10450 = "Apparently, Beretta is Raphael's Master!",
  str_homeland_secret_msg_10451 = "Beretta's two spears can move by themselves, so don't get anywhere near her at night!",
  str_homeland_secret_msg_10452 = "Goldie seem to hate all things bitter!",
  str_homeland_secret_msg_10453 = "Goldie's dog is also a huge star. It starred in a commercial before!",
  str_homeland_secret_msg_10454 = "I heard Goldie screaming once! I think she was trying on something too tight...",
  str_homeland_secret_msg_10455 = "Don't get on Goldie's bad side... Although she looks like an angelic idol, she can be very violent.",
  str_homeland_secret_msg_10456 = "Vic may look young, but he's actually an old geezer...",
  str_homeland_secret_msg_10457 = "The last time I saw Vic fall asleep, he cried with that furry animal of his in his arms, saying, \"I can't eat any more...\"",
  str_homeland_secret_msg_10458 = "You can hear birds chirping in Vic's room all night long. It's to get any sleep around here.",
  str_homeland_secret_msg_10459 = "Vic isn't much of a drinker at all! His wondrous beasts usually drink all the booze he stashes.",
  str_homeland_secret_msg_10460 = "Brandy actually won the Umbraton Arm Wrestling Tournament once! She's so strong!",
  str_homeland_secret_msg_10461 = "Even the Chubbs have started to gossip since Brandy arrived.",
  str_homeland_secret_msg_10462 = "The gossip Brandy's always spouting may actually all be true. After all, she's an honest girl.",
  str_homeland_secret_msg_10463 = "I heard Zhong Xu's family all turned into cats!",
  str_homeland_secret_msg_10464 = "Zhong Xu's wheelchair can supposedly fly!",
  str_homeland_secret_msg_10465 = "Zhong Xu seems to have no sense of direction. He's always searching around for a \"compass.\"",
  str_homeland_secret_msg_10466 = "Zhong Xu can't fight to save his life. He used to be a civil servant, that's why he has so many little cultural artisan items.",
  str_homeland_secret_msg_10467 = "Yuebai allegedly can't swim, so how did she become a ship's captain?",
  str_homeland_secret_msg_10468 = "I feel like whenever Yuebai smiles, something bad is about to happen...",
  str_homeland_secret_msg_10469 = "Yuebai's surname used to be Sen!",
  str_homeland_secret_msg_10470 = "Yuebai wears full mail armor all the time, like she thinks someone is going to try assassinating her in the night!",
  str_homeland_secret_msg_10471 = "I heard that Liqing could eat anything! He particularly loves all kinds of grass... Maybe he was a goat in a past life!",
  str_homeland_secret_msg_10472 = "Actually, Liqing's medicine is prepared according to his master's medical teachings. He hasn't come up with any ideas himself.",
  str_homeland_secret_msg_10473 = "Liqing apparently has a cat as a brother!",
  str_homeland_secret_msg_10474 = "Nemesis won the Illumina Rap Contest!",
  str_homeland_secret_msg_10475 = "Nemesis learned how to teleport from members of the Courier Union!",
  str_homeland_secret_msg_10476 = "It turns out that all the liquor Siobhan has been drinking is non-alcoholic, but she gets drunk anyway. What can I say...",
  str_homeland_secret_msg_10477 = "Siobhan came to Cloud Gardens to excavate Colossus statues supposedly buried by the Caelestites.",
  str_homeland_secret_msg_10478 = "Apparently, Siobhan used to be a movie star in Umbraton!",
  str_homeland_secret_msg_10479 = "Jeriah sleeps with her snake at night... How terrifying!",
  str_homeland_secret_msg_10480 = "Rumor has it that Jeriah is the princess of a desert tribe!",
  str_homeland_secret_msg_10481 = "Since Jeriah came here, the dormitories have become much livelier recently with the cries of all kinds of animals...",
  str_homeland_secret_msg_10482 = "Jeriah appears to be a vegetarian...",
  str_homeland_secret_msg_10483 = "Kya seems to have a photographic memory! Impressive!",
  str_homeland_secret_msg_10484 = "Although Kya seems unreliable, in fact, she's actually very mature! Why else would she be so good at her job?",
  str_homeland_secret_msg_10485 = "Kya hates the cold, that's why she's always delivering letters.",
  str_homeland_secret_msg_10486 = "Is it true that Cuscuta brings good luck with her wherever she goes?",
  str_homeland_secret_msg_10487 = "Cuscuta actually has insomnia. Her eyes are wide open even when she's asleep.",
  str_homeland_secret_msg_10488 = "Fia's water gun isn't filled with water but something that can freeze you instantly!",
  str_homeland_secret_msg_10489 = "Fia actually has a very lovely voice. Many people can't forget it after hearing her speak.",
  str_homeland_secret_msg_10490 = "Fia sometimes makes \"Lo... Lo\" sounds. Is she sick?",
  str_homeland_secret_msg_10491 = "Tina's drowsiness is fake. The truth is she has insomnia...",
  str_homeland_secret_msg_10492 = "The sound of snoring has filled the dormitory ever since Tina moved in.",
  str_homeland_secret_msg_10493 = "It seems like good things happen whenever Tina opens her eyes.",
  str_homeland_secret_msg_10494 = "Tina once traveled with an Eclipsite!",
  str_homeland_secret_msg_10495 = "Look at Leyn's mechanical weapon. I heard Illumina made it for him.",
  str_homeland_secret_msg_10496 = "Leyn has a long-lost brother who seems to be in Rediesel Desert.",
  str_homeland_secret_msg_10497 = "I saw Leyn with some fellows from Rediesel Wrench a few days ago. Is he thinking of defecting to them?",
  str_homeland_secret_msg_10498 = "Leyn has talked in his sleep a few times. It seems that he really wants a family.",
  str_homeland_secret_msg_10499 = "The truth is, Matthieu doesn't know how to try cases!",
  str_homeland_secret_msg_10500 = "Since Matthieu moved in, someone seems to be cleaning the dormitory every day. The rooms are so clean now.",
  str_homeland_secret_msg_10501 = "I heard that Matthieu's family runs a jewelry business.",
  str_homeland_secret_msg_10502 = "In fact, Hati loves collecting dolls, and you can be sure that a great many can be found in her home.",
  str_homeland_secret_msg_10503 = "Hati has a super-high intelligence, and there's no crossword puzzle she cannot solve.",
  str_homeland_secret_msg_10504 = "It appears as though Hati was raised by some kind of strange beast...?",
  str_homeland_secret_msg_10505 = "Hati is very good at cooking! Her specialty is meat stew!",
  str_homeland_secret_msg_10506 = "Since Kristen moved in, she has asked everyone to fold their quilts into a square!",
  str_homeland_secret_msg_10507 = "Kristen once practiced with her lance in her room, until she ended up poking a hole through the ceiling...",
  str_homeland_secret_msg_10508 = "Kristen's dream is to be the heroine of an opera show!",
  str_homeland_secret_msg_10509 = "Don't be fooled because Yingel likes to shoot from a distance. She's actually short-sighted.",
  str_homeland_secret_msg_10510 = "Yingel drank too much of a certain milk a few days ago and was hiccupping all night.",
  str_homeland_secret_msg_10511 = "It seems that Yingel will get sick after drinking sparkling water, so be careful!",
  str_homeland_secret_msg_10512 = "Some sort of bird seems to have built a nest around here ever since Yingel moved in.",
  str_homeland_secret_msg_10513 = "Shocking! Leo actually likes to eat raw meat?!",
  str_homeland_secret_msg_10514 = "It seems that Leo brings a bathtub whenever he fights.",
  str_homeland_secret_msg_10515 = "It seems that Leo can draw maps in his head.",
  str_homeland_secret_msg_10516 = "It's said that Leo's ambition is to become the new City Lord of Lumopolis.",
  str_homeland_secret_msg_10517 = "Don't get on the bad side of Anatoli. He'll note it down in his notebook and find a chance to get revenge.",
  str_homeland_secret_msg_10518 = "Anatoli has excellent vision, he can see things clearly from very far away, and can read lips...",
  str_homeland_secret_msg_10519 = "Don't catch Anatoli's attention, or else he'll do everything he can to observe you...",
  str_homeland_secret_msg_10520 = "Does he really live here? I haven't even seen him around that much...",
  str_homeland_secret_msg_10521 = "That fellow seems to get younger than before!",
  str_homeland_secret_msg_10522 = "I heard that the Schwartz family has a secret technique for staying forever young! No wonder they've managed to rule Lumopolis for so long!",
  str_homeland_secret_msg_10523 = "She's become so powerful recently! Has she been sneaking off somewhere to practice?",
  str_homeland_secret_msg_10524 = "After she arrived, was it my imagination, or was her room filled with the smell of tea...?",
  str_homeland_secret_msg_10525 = "A princess of Lumopolis has just moved in!",
  str_homeland_secret_msg_10526 = "Ah! It seems we have a spider infestation.... And it's a big one!",
  str_homeland_secret_msg_10527 = "I feel as though I keep hearing someone calling \"Carleen, Carleen\" late at night?",
  str_homeland_secret_msg_10528 = "Since Jakine from Northland moved in, I've noticed frequent flashes of light in the dormitories.",
  str_homeland_secret_msg_10529 = "Snake! Jakine brought a snake here!",
  str_homeland_secret_msg_10530 = "Jakine doesn't sleep at night! She just wants to party all the time!",
  str_homeland_secret_msg_20001 = "{1} and {2} have very different lifestyles and habits. A new \"Illumina vs. Lumopolis\" will soon be taking place in the dorm, mark my words.",
  str_homeland_secret_msg_20002 = "{1} wanted to open the windows, and {2} wanted them shut. So they kept on opening and closing the windows all night...",
  str_homeland_secret_msg_20003 = "Since {1} moved in, {2}'s been hearing strange noises, and now she wants to move out...",
  str_homeland_secret_msg_20004 = "Now that both {1} and {2} moved in, even the air feels sophisticated. Oh, but I'm no fan of theirs!",
  str_homeland_secret_msg_20005 = "Don't let {1} and {2} live together. I heard that {1} got cheated by {2} in the past, so they'll definitely get into fights. Wait. No. The fights have begun yesterday already!",
  str_homeland_secret_msg_20006 = "{1} loves spending time with {2}! Not that I like \"them,\" but I do like the natural air-con they make...",
  str_homeland_secret_msg_20007 = "Anyone here who lives with {1} and {2}? It's so quiet that you can hear the slightest of sounds...",
  str_homeland_secret_msg_30001 = "With {1} and {2} around, even the dorm feels like a military camp... They just won't stop talking about strategies and tactics.",
  str_homeland_secret_msg_30002 = "{1} said one must face the \"truth\" while {2} said to \"be real.\" I thought they were having a philosophical argument, but it turned out they were discussing what to have for dinner.",
  str_homeland_secret_msg_30003 = "Does anybody understand what {1} and {2} are talking about? I know every word they speak, but I don't have the faintest idea whatever do they mean... Is this the rumored \"Umbraton-speak\"?",
  str_homeland_secret_msg_30004 = "\"Birdie!\" {1} seems to love {2}'s feathers. Could it be because that {1} is also an animal? Hmm... Must be so!",
  str_homeland_secret_msg_30005 = "As far as I know, {1} and {2} break a lot of mugs. 51, just yesterday. Is that how they practice shooting?",
  str_homeland_secret_msg_30006 = "I heard that {2} ate all the food {1} cooked before it could even be plated...",
  str_homeland_secret_msg_30007 = "I heard strange calls a few nights ago. At first, {2} thought it was the pets, but then it turned out to be {1}... I mean, pets? Haha...",
  str_homeland_secret_msg_30008 = "You can feel the air stiffens as soon as {1} and {2} are in the room. Has anybody ever had that experience?",
  str_homeland_secret_msg_30009 = "A few days ago, {2} showed off some skills. {1} didn't say anything, but when I got back to the dorm, I heard {1} murmuring something about \"Illumina sure is impressive.\"",
  str_homeland_secret_msg_30010 = "{1} always says {2} doesn't understand music, but that's also what {2} says about {1}... What a pair.",
  str_homeland_secret_msg_30011 = "Lately, {2} often has long talks with {1}. I heard a new book is coming out soon!",
  str_homeland_secret_msg_30012 = "{2} seems to need to go back to the Far East, and {1} is going to tag along.",
  str_homeland_secret_msg_30013 = "Someone's been tailing {1} and taking pictures. {2} is trying to figure it out... Who could it be?",
  str_homeland_secret_msg_30014 = "{1} and {2} seem to have found something of great value. They've been traveling around without a care for the world lately.",
  str_homeland_secret_msg_30015 = "{2} seems to have caught whatever {1}'s got a few days ago. I hope it's not gonna turn into a pandemic here...",
  str_homeland_secret_msg_30016 = "{1} told a story about how \"{2} took over this place and ruled it\" while dreaming.",
  str_homeland_secret_msg_30017 = "I heard that {1} borrowed some Nightium from {2} but never paid it back. As a result, you can often hear something being sharpened around here.",
  str_homeland_secret_msg_30018 = "Some say that it was {1} and {2} who secretly patched up the holes on the roof of the dorm.",
  str_homeland_secret_msg_30019 = "{1} and {2} seem to sleepwalk. They got out for quite a few nights.",
  str_homeland_secret_msg_30020 = "{1} seems to have gained some weight while {2} lost some. Weight transference is a thing now.",
  str_homeland_secret_msg_30021 = "{1} and {2} often got into fights about the Fireflies for some reason.",
  str_homeland_secret_msg_30022 = "I saw {1} and {2} going through the Navigator's journal in secret. They must be planning something against the Navigator!",
  str_homeland_secret_msg_30023 = "I heard that {1} and {2} made a wager on the side of the dorm room with a better view."
}
return config
